 const xa=qOther(y-1,qa,rc),xb=qOther(y,qb,rc);if(xa==null||xb==null)continue;const wr1=Object.entries(Q[y][qb].rc).sort((p,q)=>q[1][0]-p[1][0])[0][0]===rc;
